import pandas as pd

def implementation_shortfall(trades, decision_price, side="buy"):
    required = {"price", "quantity"}
    missing = required - set(trades.columns)
    if missing:
        raise ValueError(f"Missing columns: {missing}")

    total_qty = trades["quantity"].sum()
    if total_qty <= 0:
        raise ValueError("Total quantity must be positive")

    avg_exec_price = (trades["price"] * trades["quantity"]).sum() / total_qty

    if side == "buy":
        per_share_shortfall = avg_exec_price - decision_price
    elif side == "sell":
        per_share_shortfall = decision_price - avg_exec_price
    else:
        raise ValueError("side must be 'buy' or 'sell'")

    return {
        "average_execution_price": avg_exec_price,
        "per_share_shortfall": per_share_shortfall,
        "total_shortfall": per_share_shortfall * total_qty,
    }

