def newton(f, df, x0, tol=1e-8, max_iter=50):
    x = float(x0)
    for _ in range(max_iter):
        fx = f(x)
        dfx = df(x)
        if abs(dfx) < 1e-12:
            raise ValueError('Derivative too close to zero')
        x_new = x - fx / dfx
        if abs(x_new - x) < tol:
            return x_new
        x = x_new
    return x

