def max_subarray_sum(values):
    if not values:
        raise ValueError('values cannot be empty')

    best_end_here = values[0]
    best = values[0]

    for x in values[1:]:
        best_end_here = max(x, best_end_here + x)
        best = max(best, best_end_here)

    return best

