class RollingMean:
    def __init__(self, window):
        if window <= 0:
            raise ValueError('window must be positive')
        self.window = window
        self.values = deque()
        self.total = 0.0

    def update(self, x):
        self.values.append(float(x))
        self.total += float(x)

        if len(self.values) > self.window:
            self.total -= self.values.popleft()

        return self.total / len(self.values)

